#define _GNU_SOURCE
#include "storage/qrx_drive_private_pq.h"
#include "storage/qrx_drive_crypto.h"
#include <openssl/evp.h>
#include <openssl/crypto.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#define MAGIC "QRXPQ1\0\0"
static void p32(unsigned char*b,uint32_t v){b[0]=v>>24;b[1]=v>>16;b[2]=v>>8;b[3]=v;}
static void p64(unsigned char*b,uint64_t v){for(int i=7;i>=0;i--){b[i]=(unsigned char)v;v>>=8;}}
static uint32_t g32(const unsigned char*b){return ((uint32_t)b[0]<<24)|((uint32_t)b[1]<<16)|((uint32_t)b[2]<<8)|b[3];}
static uint64_t g64(const unsigned char*b){uint64_t v=0;for(int i=0;i<8;i++)v=(v<<8)|b[i];return v;}
static int wr(FILE*f,EVP_MD_CTX*h,const void*p,size_t n){return fwrite(p,1,n,f)==n&&EVP_DigestUpdate(h,p,n)==1?0:-1;}
static int digest_file_prefix(FILE*f,uint64_t n,unsigned char out[64]){if(fseek(f,0,SEEK_SET))return-1;EVP_MD_CTX*h=EVP_MD_CTX_new();if(!h)return-1;int rc=-1;unsigned char b[65536];uint64_t left=n;unsigned z=0;if(EVP_DigestInit_ex(h,EVP_sha3_512(),NULL)!=1)goto done;while(left){size_t q=left>sizeof(b)?sizeof(b):(size_t)left;if(fread(b,1,q,f)!=q||EVP_DigestUpdate(h,b,q)!=1)goto done;left-=q;}if(EVP_DigestFinal_ex(h,out,&z)==1&&z==64)rc=0;done:EVP_MD_CTX_free(h);return rc;}
static int sign_digest(EVP_PKEY*k,const unsigned char h[64],unsigned char**sig,size_t*n){EVP_MD_CTX*c=EVP_MD_CTX_new();if(!c)return-1;int rc=-1;size_t z=0;unsigned char*s=NULL;if(EVP_DigestSignInit_ex(c,NULL,NULL,NULL,NULL,k,NULL)!=1||EVP_DigestSign(c,NULL,&z,h,64)!=1||!z)goto done;s=malloc(z);if(!s)goto done;if(EVP_DigestSign(c,s,&z,h,64)!=1)goto done;*sig=s;*n=z;s=NULL;rc=0;done:free(s);EVP_MD_CTX_free(c);return rc;}
static int verify_digest(EVP_PKEY*k,const unsigned char h[64],const unsigned char*sig,size_t n){EVP_MD_CTX*c=EVP_MD_CTX_new();if(!c)return-1;int ok=EVP_DigestVerifyInit_ex(c,NULL,NULL,NULL,NULL,k,NULL)==1&&EVP_DigestVerify(c,sig,n,h,64)==1;EVP_MD_CTX_free(c);return ok?0:-1;}
int qrx_drive_private_pq_encrypt_file(const char*source,const char*container,EVP_PKEY*kem,EVP_PKEY*signer,uint64_t*plain_n,uint64_t*cipher_n){if(!source||!container||!kem||!signer)return-1;struct stat st;if(stat(source,&st)||st.st_size<0)return-1;FILE*in=fopen(source,"rb"),*out=fopen(container,"wb+");if(!in||!out){if(in)fclose(in);if(out)fclose(out);return-1;}int rc=-1;unsigned char key[32]={0},salt[32]={0};QrxDriveKeyEnvelope e={0};EVP_MD_CTX*h=EVP_MD_CTX_new();unsigned char*buf=NULL,*sig=NULL;size_t siglen=0;if(!h||qrx_drive_random_file_key(key)||RAND_bytes(salt,32)!=1||qrx_drive_wrap_file_key(kem,key,&e))goto done;buf=malloc(QRX_DRIVE_PRIVATE_PQ_CHUNK);if(!buf||EVP_DigestInit_ex(h,EVP_sha3_512(),NULL)!=1)goto done;unsigned char hdr[32]={0};memcpy(hdr,MAGIC,8);p32(hdr+8,1);p32(hdr+12,QRX_DRIVE_PRIVATE_PQ_CHUNK);p64(hdr+16,(uint64_t)st.st_size);p32(hdr+24,(uint32_t)e.kem_ciphertext_len);if(wr(out,h,hdr,sizeof(hdr))||wr(out,h,salt,32)||wr(out,h,e.kem_ciphertext,e.kem_ciphertext_len)||wr(out,h,e.wrapped_file_key,32)||wr(out,h,e.nonce,12)||wr(out,h,e.tag,16))goto done;uint64_t idx=0,seen=0;for(;;){size_t n=fread(buf,1,QRX_DRIVE_PRIVATE_PQ_CHUNK,in);if(n){unsigned char aad[44];memcpy(aad,salt,32);p64(aad+32,idx);p32(aad+40,(uint32_t)n);QrxDriveCiphertext ct={0};if(qrx_drive_encrypt(key,buf,n,aad,sizeof(aad),&ct))goto done;unsigned char ch[4];p32(ch,(uint32_t)n);int bad=wr(out,h,ch,4)||wr(out,h,ct.nonce,12)||wr(out,h,ct.tag,16)||wr(out,h,ct.ciphertext,ct.ciphertext_len);qrx_drive_ciphertext_free(&ct);if(bad)goto done;seen+=n;idx++;}if(n<QRX_DRIVE_PRIVATE_PQ_CHUNK){if(ferror(in))goto done;break;}}if(seen!=(uint64_t)st.st_size)goto done;unsigned char dh[64];unsigned z=0;if(EVP_DigestFinal_ex(h,dh,&z)!=1||z!=64||sign_digest(signer,dh,&sig,&siglen)||siglen>UINT32_MAX)goto done;unsigned char sl[4];p32(sl,(uint32_t)siglen);if(fwrite(sl,1,4,out)!=4||fwrite(sig,1,siglen,out)!=siglen||fflush(out))goto done;if(plain_n)*plain_n=(uint64_t)st.st_size;if(cipher_n){long x=ftell(out);if(x<0)goto done;*cipher_n=(uint64_t)x;}rc=0;done:OPENSSL_cleanse(key,sizeof(key));free(buf);free(sig);qrx_drive_key_envelope_free(&e);EVP_MD_CTX_free(h);fclose(in);fclose(out);if(rc)remove(container);return rc;}
int qrx_drive_private_pq_decrypt_file(const char*container,const char*destination,EVP_PKEY*kem,EVP_PKEY*signer,uint64_t*plain_n){if(!container||!destination||!kem||!signer)return-1;FILE*in=fopen(container,"rb");if(!in)return-1;if(fseek(in,0,SEEK_END)){fclose(in);return-1;}long fl=ftell(in);if(fl<40||fseek(in,0,SEEK_SET)){fclose(in);return-1;}unsigned char hdr[32],salt[32];if(fread(hdr,1,32,in)!=32||memcmp(hdr,MAGIC,8)||g32(hdr+8)!=1||fread(salt,1,32,in)!=32){fclose(in);return-1;}uint32_t chunk=g32(hdr+12),kemlen=g32(hdr+24);uint64_t expected=g64(hdr+16);if(chunk<65536||chunk>64u*1024u*1024u||!kemlen||kemlen>1024*1024){fclose(in);return-1;}QrxDriveKeyEnvelope e={0};e.kem_ciphertext=malloc(kemlen);e.kem_ciphertext_len=kemlen;if(!e.kem_ciphertext||fread(e.kem_ciphertext,1,kemlen,in)!=kemlen||fread(e.wrapped_file_key,1,32,in)!=32||fread(e.nonce,1,12,in)!=12||fread(e.tag,1,16,in)!=16){qrx_drive_key_envelope_free(&e);fclose(in);return-1;}uint64_t fixed=32+32+kemlen+32+12+16, pos=fixed,plain_seen=0;while(plain_seen<expected){if(pos+32>(uint64_t)fl){qrx_drive_key_envelope_free(&e);fclose(in);return-1;}unsigned char l[4];if(fseek(in,(long)pos,SEEK_SET)||fread(l,1,4,in)!=4){qrx_drive_key_envelope_free(&e);fclose(in);return-1;}uint32_t n=g32(l);if(!n||n>chunk||plain_seen+n>expected){qrx_drive_key_envelope_free(&e);fclose(in);return-1;}pos+=4+12+16+n;plain_seen+=n;}if(pos+4>(uint64_t)fl||fseek(in,(long)pos,SEEK_SET)){qrx_drive_key_envelope_free(&e);fclose(in);return-1;}unsigned char sl[4];if(fread(sl,1,4,in)!=4){qrx_drive_key_envelope_free(&e);fclose(in);return-1;}uint32_t siglen=g32(sl);if(!siglen||pos+4+siglen!=(uint64_t)fl){qrx_drive_key_envelope_free(&e);fclose(in);return-1;}unsigned char*sig=malloc(siglen),dh[64];if(!sig||fread(sig,1,siglen,in)!=siglen||digest_file_prefix(in,pos,dh)||verify_digest(signer,dh,sig,siglen)){free(sig);qrx_drive_key_envelope_free(&e);fclose(in);return-1;}free(sig);unsigned char key[32]={0};if(qrx_drive_unwrap_file_key(kem,&e,key)){qrx_drive_key_envelope_free(&e);fclose(in);return-1;}qrx_drive_key_envelope_free(&e);FILE*out=fopen(destination,"wb");if(!out){OPENSSL_cleanse(key,32);fclose(in);return-1;}int rc=-1;uint64_t idx=0,seen=0;pos=fixed;while(seen<expected){unsigned char l[4],nonce[12],tag[16];if(fseek(in,(long)pos,SEEK_SET)||fread(l,1,4,in)!=4||fread(nonce,1,12,in)!=12||fread(tag,1,16,in)!=16)goto done;uint32_t n=g32(l);unsigned char*ct=malloc(n);if(!ct||fread(ct,1,n,in)!=n){free(ct);goto done;}QrxDriveCiphertext c={ct,n,{0},{0}};memcpy(c.nonce,nonce,12);memcpy(c.tag,tag,16);unsigned char aad[44];memcpy(aad,salt,32);p64(aad+32,idx);p32(aad+40,n);unsigned char*p=NULL;size_t pn=0;if(qrx_drive_decrypt(key,&c,aad,sizeof(aad),&p,&pn)||pn!=n){free(ct);free(p);goto done;}free(ct);if(fwrite(p,1,pn,out)!=pn){OPENSSL_cleanse(p,pn);free(p);goto done;}OPENSSL_cleanse(p,pn);free(p);seen+=pn;pos+=4+12+16+n;idx++;}if(fflush(out)==0){if(plain_n)*plain_n=seen;rc=0;}done:OPENSSL_cleanse(key,32);fclose(in);if(fclose(out)||rc) {remove(destination);rc=-1;}return rc;}
